import os, json

d = os.environ.get('RLM_SESSION_DIR', '')
t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')

# Find all message types
types = set()
for line in t.split('\n'):
    try:
        obj = json.loads(line)
        if 'type' in obj:
            types.add(obj['type'])
        elif 'role' in obj:
            types.add(obj['role'])
    except:
        pass

print("Types found:", types)

# Look for role:assistant messages with demo data
lines = t.split('\n')
count = 0
for line in lines:
    if line.startswith('{"type":"message"'):
        count += 1
        if count % 10 == 0:
            print(f"Message {count}:")
            # Parse this message
            start_idx = t.index(line)
            end_idx = t.index('\n' + ('{"type":"' if count > 1 else '{'), start_idx+1)
            if end_idx > start_idx:
                msg_data = t[start_idx:end_idx+1]
                try:
                    msg = json.loads(msg_data)
                    role = msg.get('role', '')
                    if role in ['assistant', 'toolResult']:
                        content = msg.get('content', [])
                        for c in content:
                            if isinstance(c, dict) and c.get('type') == 'text':
                                txt = c.get('text', '')
                                if 'Demo pair' in txt or '0 2' in txt or '1 2' in txt:  # grids
                                    print(txt[:500])
                except:
                    pass

